#!/usr/bin/env python3
"""Build source-controlled RSC commercial site. No secrets, external writes or CRM API."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parents[1]
NAV=[("Capabilities","/services.html"),("Approach","/approach.html"),("Research","/research.html"),("Evidence","/evidence.html"),("About","/about.html")]
SERVICES=[
 ("01","Cyber Resilience","Reduce uncertainty about critical systems, dependencies, recovery paths, and security decisions.","/resilience.html"),
 ("02","Security Operations","Design practical detection, response, identity and observability workflows with accountable operating boundaries.","/security-operations.html"),
 ("03","Post-Quantum Readiness","Plan a standards-informed cryptographic inventory, prioritization and migration path without premature compliance claims.","/post-quantum.html"),
]
def esc(s):return escape(str(s),quote=True)
def cards(items):
 return '<div class="grid grid-3">'+''.join(f'<article class="card"><span class="number">{esc(n)}</span><h3>{esc(h)}</h3><p>{esc(p)}</p><a href="{esc(u)}">Explore capability →</a></article>' for n,h,p,u in items)+'</div>'
def header(current):
 links=''.join(f'<a href="{u}" '+('aria-current="page"' if current==u else '')+f'>{n}</a>' for n,u in NAV)
 return '<a class="skip" href="#content">Skip to content</a><header class="site-header"><div class="shell nav"><a class="brand" href="/" aria-label="Restoration Security Consultants home"><span class="mark" aria-hidden="true">R</span><span class="brandname">Restoration<small>Security Consultants</small></span></a><button class="nav-toggle" aria-label="Toggle navigation" aria-expanded="false" aria-controls="main-nav">Menu</button><nav id="main-nav" class="nav-links" aria-label="Primary navigation">'+links+'<a class="nav-cta" href="/engage.html">Start a conversation</a></nav></div></header>'
def footer():
 return '<section class="cta-band"><div class="shell cta-layout"><div><h2>Security decisions deserve evidence.</h2><p>Bring the problem, the timeline, and the outcome that matters.</p></div><a class="btn btn-gold" href="/engage.html">Discuss a challenge →</a></div></section><footer class="site-footer"><div class="shell"><div class="footer-top"><div><a class="brand" href="/"><span class="mark" aria-hidden="true">R</span><span class="brandname">Restoration<small>Security Consultants</small></span></a><p style="max-width:390px;margin-top:22px">Engineering trust. Demonstrating resilience.<br>Scoped cybersecurity engineering and evidence-led technical strategy.</p></div><div><h3>Explore</h3><a href="/services.html">Capabilities</a><a href="/approach.html">Our approach</a><a href="/evidence.html">Evidence standard</a><a href="/capability-statement.html">Capability statement</a></div><div><h3>Contact and policies</h3><a href="/engage.html">Engage RSC</a><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms of use</a><a href="https://pqexpert.io/" rel="noopener">PQExpert — separate practice ↗</a></div></div><div class="footer-bottom"><span>© 2026 Restoration Security Consultants. All rights reserved.</span><span>Independent commercial security practice. No government affiliation or endorsement is implied.</span></div></div></footer>'
def page(name,title,description,body,canonical=None,hero=None):
 url='https://www.restoration-mt.com'+(canonical or ('/'+name))
 h=('<section class="page-intro"><div class="shell"><span class="eyebrow">Restoration Security Consultants / '+esc(name.replace('.html','').replace('-',' '))+'</span><h1>'+esc(title)+'</h1><p class="lead">'+esc(description)+'</p></div></section>') if hero is None else hero
 html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#101c2a">'''
 html+='<title>'+esc(title)+' | Restoration Security Consultants</title><meta name="description" content="'+esc(description)+'"><link rel="canonical" href="'+url+'"><meta property="og:type" content="website"><meta property="og:title" content="'+esc(title)+' | Restoration Security Consultants"><meta property="og:description" content="'+esc(description)+'"><meta property="og:url" content="'+url+'"><meta property="og:image" content="https://www.restoration-mt.com/assets/og-card.svg"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/assets/site.css"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"></head><body>'+header('/'+name)+'<main id="content">'+h+body+'</main>'+footer()+'<script src="/assets/site.js" defer></script></body></html>'
 (ROOT/name).write_text(html,encoding='utf-8')
def section(inner,soft=False,dark=False):
 return '<section class="section'+(' soft' if soft else '')+(' dark' if dark else '')+'"><div class="shell">'+inner+'</div></section>'
def heading(k,h,p=''):
 return '<div class="section-head"><span class="eyebrow">'+esc(k)+'</span><h2>'+esc(h)+'</h2>'+('<p>'+esc(p)+'</p>' if p else '')+'</div>'
def intro(k,h,p):
 return '<section class="hero"><div class="shell"><span class="eyebrow">'+esc(k)+'</span><h1>'+esc(h)+'</h1><p class="lede">'+esc(p)+'</p><div class="actions"><a class="btn btn-gold" href="/engage.html">Discuss a security challenge</a><a class="btn btn-outline" href="/services.html">Review capabilities</a></div><div class="factbar"><span>Evidence before claims</span><span>Defined scope</span><span>Technical accountability</span></div></div></section>'
home=intro('Cyber resilience / security engineering / applied research','Security engineering for decisions that matter.','Restoration Security Consultants helps organizations turn technical risk into disciplined, testable action. Clarity first. Scope that fits. Evidence that survives scrutiny.')
home+=section(heading('Our capabilities','Practical security work, honestly described.','From initial assessment to a defensible plan, with delivery boundaries established before commitments.')+cards(SERVICES))
home+=section('<div class="split"><div><span class="eyebrow">A different standard</span><h2>No borrowed credibility. No black-box promises.</h2><p class="lead">An impressive assertion is not a control. We distinguish deployed results from research, demonstrate the evidence behind claims, and set explicit decision points throughout the work.</p><a class="btn btn-dark" href="/evidence.html">Read our evidence standard →</a></div><div class="aside"><h3>What you can expect</h3><p>A bounded discovery process, an accountable owner, clear acceptance criteria, and a documented recommendation or implementation plan.</p><p>Credentials, customer outcomes and production availability are represented only when verified.</p></div></div>',soft=True)
home+=section(heading('How we operate','From ambiguity to an actionable next step.')+'<div class="steps">'+''.join(f'<div class="step"><h3>{h}</h3><p>{p}</p></div>' for h,p in [('Define','Clarify the decision, environment, stakeholders, and authority.'),('Investigate','Gather source evidence, dependencies, and the actual constraints.'),('Act','Deliver the smallest defensible assessment, plan, or pilot.'),('Verify','Document what changed, what did not, and what comes next.')])+'</div>')
page('index.html','Security engineering for decisions that matter.','Cyber resilience, security operations and post-quantum readiness planning through Restoration Security Consultants.',home,canonical='/',hero='')
# replace default intro variant on homepage with bespoke hero
s=(ROOT/'index.html').read_text();s=s.replace('<main id="content"></main>','<main id="content">'+home+'</main>');(ROOT/'index.html').write_text(s)
services=section(heading('Technical capabilities','Three connected disciplines.','Every engagement begins with a specific organizational problem, not a sales bundle.')+cards(SERVICES)+ '<div class="aside" style="margin-top:32px"><h3>Research versus delivery</h3><p>Post-quantum work, detection research and agent-assisted operations may be offered as analysis, advisory, or pilot work. We do not describe prototypes as independently certified production systems.</p></div>')
page('services.html','Cybersecurity capabilities','Cyber resilience, security operations and post-quantum readiness planning for institutions and businesses.',services)
for name,title,lead,areas in [
('resilience.html','Cyber resilience & recovery','Understand what matters, how it can fail, and the smallest practical steps toward a more recoverable operating environment.',[('System criticality','Map the services, dependencies, recovery requirements and decision owners.'),('Control and failure review','Assess configurations, identity boundaries, existing controls and realistic failure paths.'),('Action plan','Prioritize response, recovery and governance actions with acceptance criteria.')]),
('security-operations.html','Security operations modernization','Turn telemetry, access controls and response workflows into reliable operational decisions.',[('Detection and evidence','Examine monitoring sources, alert quality, triage evidence, and accountable escalation.'),('Identity and access','Review operational access, policy ownership, least privilege and recovery.'),('Response workflow','Design actionable case routing, outcomes tracking and safe automation boundaries.')]),
('post-quantum.html','Post-quantum readiness','Inventory cryptographic dependencies and plan measured transitions based on current standards and organizational risk.',[('Cryptographic inventory','Identify affected products, protocols, vendors, data longevity and ownership.'),('Prioritization','Separate immediate protective steps from longer-term cryptographic transitions.'),('Migration roadmap','Create change sequencing, vendor questions, validation tests and risk records.')])]:
 body=section(heading('Engagement focus','What the work can cover.')+'<div class="grid grid-3">'+''.join(f'<article class="card"><span class="number">0{i}</span><h3>{esc(h)}</h3><p>{esc(p)}</p></article>' for i,(h,p) in enumerate(areas,1))+'</div>')
 body+=section('<div class="split"><div><span class="eyebrow">Engagement approach</span><h2>Start with a useful decision.</h2><p class="lead">A scoped review, working session, or pilot is chosen only after the goal and evidence requirements are understood. No automatic certification, compliance outcome or time-to-result promise.</p><a class="btn btn-dark" href="/engage.html">Scope this work →</a></div><div class="aside"><h3>Typical outputs</h3><p>An evidence register, an actionable risk or dependency map, and a prioritized technical plan. Exact deliverables are established in the engagement scope.</p></div></div>',soft=True)
 page(name,title,lead,body)
approach=section(heading('Delivery doctrine','Proof is part of the work.')+'<div class="steps">'+''.join(f'<div class="step"><h3>{h}</h3><p>{p}</p></div>' for h,p in [('Listen','Understand the operational decision and who is accountable.'),('Validate','Separate confirmed facts from assumptions, research and unknowns.'),('Execute','Use authorized tools and controlled changes appropriate to scope.'),('Close','Confirm results, limitations, handoff and the next useful step.')])+'</div>')
approach+=section('<div class="split"><div><h2>Human authority where it matters.</h2><p class="lead">Automation can help investigate, prepare, classify and execute bounded work. Contracting, access, compliance conclusions, organizational commitments and consequential decisions stay within the responsible legal and human authority.</p></div><div class="aside"><h3>Engagement evidence</h3><p>We distinguish successful tool execution, provider-verified changes, customer outcomes and independent validation. Those are different statements, and we report them separately.</p></div></div>',soft=True)
page('approach.html','An accountable engineering approach','Define the mission, investigate real evidence, act within scope and verify business effects.',approach)
research=section(heading('Research directions','Applied investigation, not product theater.','Current topics are presented as research and emerging implementation until their operating maturity is independently established.')+'<div class="grid grid-3">'+''.join(f'<article class="card"><span class="tag">Research / active development</span><h3 style="margin-top:24px">{h}</h3><p>{p}</p><a href="/engage.html">Discuss the topic →</a></article>' for h,p in [('Post-quantum transition','Inventories, migration sequencing and standards-aware decisions.'),('Threat-model evolution','Keeping evidence, hypotheses and unknowns distinguishable through change.'),('Detection and automation','Deterministic analytics, local AI interpretation and bounded operational workflows.')])+'</div>')
page('research.html','Applied security research','Practical investigation across post-quantum readiness, detection engineering and governed automation.',research)
evidence=section('<div class="prose"><span class="eyebrow">Our claim standard</span><h2>We say exactly what is proved.</h2><p class="lead">A customer-facing statement is only as reliable as its source, its boundaries and its most recent verification.</p><h3>Verified</h3><p>Evidence-backed implementation or outcome supported by an attributable source and an actual result check.</p><h3>In development</h3><p>Source, prototype, or tested component exists, but operational adoption or customer effect remains unproven.</p><h3>Research / concept</h3><p>Investigation or proposed approach, not a finished product.</p><h3>Not claimed</h3><p>We do not imply NSA or government affiliation, cleared personnel, third-party certifications, named client engagements, production capabilities, statistical outcomes or service guarantees without substantiation and permission.</p><p><a href="/engage.html">Ask for source-specific evidence →</a></p></div>')
page('evidence.html','Evidence before claims','How Restoration Security Consultants distinguishes verified capability, in-development engineering and research.',evidence)
about=section('<div class="split"><div><span class="eyebrow">Restoration Security Consultants</span><h2>Built for the work that must hold up.</h2><p class="lead">We focus on operational cybersecurity, resilience and the governance of technical change. Our public posture emphasizes practical contribution, verification and clarity—not inflated credentials or generic security slogans.</p><p>RSC is the commercial security practice. PQExpert.io is a distinct co-cognitive portfolio and freelance intake surface; the two may collaborate on appropriately scoped work but are not interchangeable brands.</p><a class="btn btn-dark" href="/engage.html">Discuss an engagement →</a></div><div class="aside"><h3>Identity and accountability</h3><p>The names and titles of people are published only after verification and authorization. Engagements identify the responsible contracting organization and human decision-maker where required.</p><p>Our separate research systems do not independently confer legal authority, professional licensure or government status.</p></div></div>')
page('about.html','Restoration. Resilience. Results.','The commercial security engineering practice behind accountable cybersecurity engagements.',about)
engage=section('<div class="split" style="align-items:start"><div><span class="eyebrow">Start with context</span><h2>Tell us what needs to work better.</h2><p class="lead">A useful first message is enough to start. Describe your organization type, the problem, the decision or outcome, and the timeline—without sending credentials or sensitive system details.</p><div class="aside"><h3>What happens next</h3><p>Your inquiry is submitted through our existing HighLevel intake provider. We review whether the request is within scope, identify a responsible next step, and reply using the contact information you provide.</p><p>No response deadline or automated availability is guaranteed. A form acknowledgment is not proof of personal review.</p></div></div><div class="form-wrap"><h3>Security engineering inquiry</h3><p class="fineprint">Third-party form provider: HighLevel / LeadConnector. Do not include passwords, regulated data, or confidential infrastructure information.</p><iframe id="rsc-intake" title="RSC security engineering inquiry form" loading="lazy" referrerpolicy="no-referrer" src="https://api.leadconnectorhq.com/widget/form/z3HWJ4Zx58oSRGaBNGe8?utm_source=restoration_mt_site&utm_medium=owned_site&utm_campaign=rsc_commercial" ></iframe><p class="fineprint">If the embedded form does not load, <a href="https://api.leadconnectorhq.com/widget/form/z3HWJ4Zx58oSRGaBNGe8?utm_source=restoration_mt_site%26utm_medium=owned_site%26utm_campaign=rsc_commercial" id="direct-intake" target="_blank" rel="noopener noreferrer">open the form directly</a>. Submission is processed under the provider form privacy controls.</p></div></div>')
page('engage.html','Discuss a security challenge','Start a scoped cybersecurity, resilience or technical strategy conversation with Restoration Security Consultants.',engage)
privacy=section('<div class="prose"><h2>Information collected</h2><p>This site does not require an account. When you follow an inquiry link, an embedded third-party HighLevel / LeadConnector form may collect information that you choose to submit, including business contact information and the problem you describe. Do not submit secrets, regulated data, classified material or sensitive customer information.</p><h2>Purpose and handling</h2><p>Inquiries are used to understand your request, determine a suitable next step, and respond. The form provider may process the information under its own infrastructure and applicable privacy notices. An inquiry does not automatically enroll you in unrelated marketing.</p><h2>Analytics, embedded content and external sites</h2><p>The site does not include a first-party tracking pixel by default. External form embeds, font delivery and linked third-party services may process technical connection data. When you leave this domain, the destination service controls its own practices.</p><h2>Requests and corrections</h2><p>Use <a href="/engage.html">the contact route</a> to ask about information you submitted or request a correction or deletion where applicable. The governing privacy notice and lawful contracting disclosures should be confirmed with the actual legal entity before collecting additional categories of personal data.</p><h2>Changes</h2><p>Last editorial update: November 15, 2026.</p></div>')
page('privacy.html','Privacy & data handling','What this website collects, which providers handle inquiries, and how to request a correction.',privacy)
terms=section('<div class="prose"><h2>Informational use</h2><p>Materials on this site describe possible security engineering services and research directions. They are not legal advice, a binding offer, a guarantee of cybersecurity outcomes or a certification.</p><h2>Engagements</h2><p>Scope, fees, delivery authority, confidentiality, timelines, intellectual property and obligations are determined in written agreements with the appropriate legal entity and authorized signatories. Sending an inquiry creates no client relationship.</p><h2>Third-party references</h2><p>References to government standards, providers or research are informational and do not imply affiliation or endorsement.</p><h2>Legal accuracy</h2><p>Corporate identity and any required legal disclosures must be verified before execution of an agreement. Last editorial update: November 15, 2026.</p></div>')
page('terms.html','Terms of site use','Editorial and non-contractual terms for the Restoration Security Consultants website.',terms)
cap=section('<div class="prose"><span class="eyebrow">Capabilities overview / printable</span><h2>Engineering trust. Demonstrating resilience.</h2><p>Restoration Security Consultants provides scoped cybersecurity and security engineering planning for organizations seeking evidence-led decisions and resilient operations.</p><h3>Core focus</h3><ul><li>Cyber resilience: technical dependencies, controls, operating continuity and recovery planning</li><li>Security operations: identity governance, telemetry, detection, escalation and response design</li><li>Post-quantum readiness: cryptographic inventory, prioritization and migration planning</li><li>Applied research: threat modeling, detection architectures and bounded automation</li></ul><h3>How engagements work</h3><p>Define authority and problem → gather evidence → agree scope and deliverables → implement or advise → independently check the result and document limitations.</p><h3>Trust and verification</h3><p>We do not claim certifications, customer figures, agency relationships, cleared status or government approvals without independent supporting evidence and authorization.</p><p><strong>Engage:</strong> <a href="https://www.restoration-mt.com/engage.html">www.restoration-mt.com/engage.html</a></p><p class="fineprint">Current public capability overview; not a proposal or contract.</p><div class="actions"><button class="btn btn-dark" onclick="window.print()">Print or save as PDF</button></div></div>')
page('capability-statement.html','Capability overview','Printable overview of Restoration Security Consultants cybersecurity engineering capabilities and engagement principles.',cap)
page('404.html','Page not found','This address is not part of the current Restoration Security Consultants website.',section('<p>Return to <a href="/">the RSC homepage</a> or <a href="/engage.html">contact us</a>.</p>'))
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://www.restoration-mt.com/sitemap.xml\n')
urls=['/','/services.html','/resilience.html','/security-operations.html','/post-quantum.html','/approach.html','/research.html','/evidence.html','/about.html','/engage.html','/privacy.html','/terms.html','/capability-statement.html']
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('  <url><loc>https://www.restoration-mt.com'+x+'</loc></url>\n' for x in urls)+'</urlset>\n')
print('Built',len(urls)+1,'HTML pages')
